import {startComparisonServer} from '../../framework-comparison/src/server.mjs';
const root=path.resolve('.tmp/node-output-plan'),suite=path.resolve('framework-comparison');
const variants=[
 {id:'baseline',entry:'baseline',adapter:'node-adapter-before'},
 {id:'immediate-whole',entry:'hydration-native-count',adapter:'immediate-adapter'},
 {id:'immediate-callbacks',entry:'hydration-registered',adapter:'immediate-adapter'},
 {id:'immediate-records',entry:'hydration-records',adapter:'immediate-adapter'}
];
const runtime=availableSsrRuntimes('node')[0];
const report={createdAt:new Date().toISOString(),environment:ssrEnvironmentMetadata([runtime]),method:{populations:2,rounds:12,windowMs:500,concurrency:32,lanes:['normal','preloaded']},artifacts:{},epochs:[],runners:{run:await readFile(path.join(root,'immediate-run.mjs'),'utf8'),adapter:await readFile(path.join(root,'immediate-adapter.mjs'),'utf8')}};
for(const name of ['baseline','hydration-native-count','hydration-registered','hydration-records','confirmation-worker','immediate-adapter','node-adapter-before']){const data=await readFile(path.join(root,name+'.mjs'));report.artifacts[name]={bytes:data.length,sha256:createHash('sha256').update(data).digest('hex')};}
const service=await startComparisonServer();
try{
 for(let epoch=0;epoch<2;epoch++){
 const entries=balancedRoundOrder(variants,epoch).map(v=>({...v}));
 const startup=await settleSsrWorkerInventoryStartup(entries,entry=>startSsrWorker({runtime,participantId:entry.id==='react'?'react':'exact',environment:{COMPARISON_NODE_ADAPTER_ENTRY:path.join(root,entry.adapter+'.mjs'),...(entry.entry?{COMPARISON_EXACT_SERVER_ENTRY:path.join(root,entry.entry+'.mjs')}:{})},transport:'node-http',workerPath:path.join(root,'confirmation-worker.mjs'),workingDirectory:suite,serviceUrl:service.url}));
 try{
  if(startup.failure)throw startup.failure;
  let identity;
  for(const entry of entries){entry.identity=await measureSsrRequest(entry.worker.url);if(!entry.identity.meaningful)throw new Error(JSON.stringify({id:entry.id,identity:entry.identity,body:await(await fetch(entry.worker.url)).text(),stderr:entry.worker.stderr()}));if(entry.id!=='react'){identity??=entry.identity.hash;assert.equal(entry.identity.hash,identity,entry.id);}}
  const samples={epoch,identities:Object.fromEntries(entries.map(e=>[e.id,e.identity])),windows:[]};
  for(const lane of balancedRoundOrder(['normal','preloaded'],epoch)){
   const url=entry=>entry.worker.url+(lane==='preloaded'?'?__benchmarkPreloaded=1':'');
   for(const entry of entries){await runSustainedSsrWindow(url(entry),32,2000);await controlSsrWorker(entry.worker,'reset');}
   for(let round=0;round<12;round++)for(const entry of balancedRoundOrder(entries,round,epoch)){
    const sample=await runSustainedSsrWindow(url(entry),32,500);
    for(const result of sample.samples){assert.ok(result.meaningful);assert.equal(result.hash,entry.identity.hash);assert.equal(result.bytes,entry.identity.bytes);}
    samples.windows.push({id:entry.id,lane,round,requests:sample.samples.length,elapsedMs:sample.elapsedMs});
   }
