 }finally{for(const worker of startup.workers)await stopSsrWorker(worker);resetSsrClientConnections();}
 }
 report.summary=Object.fromEntries(['normal','preloaded'].map(lane=>[lane,Object.fromEntries(variants.map(v=>[v.id,aggregateSsrThroughput(report.epochs.flatMap(e=>e.windows).filter(s=>s.id===v.id&&s.lane===lane))]))]));
 report.complete=true;await writeFile(path.join(root,'immediate-http.json'),JSON.stringify(report,null,2));console.log('FINAL',JSON.stringify(report.summary));
}finally{await service.close();}

