import {exactResponseBodyOf} from '@exactjs/server';

/** Diagnostic: forwards every produced span to Node immediately, without an application buffer. */
export function writeNodeResponse(response,result,signal){
 const body=exactResponseBodyOf(result);
 if(body?.kind!=='produced'||!body.writeSynchronously)return joined(response,result,signal);
 return stream(response,result,body,signal);
}
async function stream(response,result,body,signal){
 response.statusCode=result.status;
 for(const[name,value]of Object.entries(result.headers))response.setHeader(name,value);
 try{
  const completion=body.writeSynchronously(chunk=>{
   signal?.throwIfAborted();
   response.write(chunk);
  },{encodedByteLength:Buffer.byteLength});
  if(completion)await completion;
  signal?.throwIfAborted();
  response.end();
 }catch(error){
  try{await body.cancel(error);}catch{}
  if(response.headersSent)response.destroy(error);
  else{response.statusCode=500;response.end('diagnostic failure');}
 }
}

