import {readFile,writeFile} from 'node:fs/promises';
const root='.tmp/node-output-plan/';
let source=await readFile(root+'hydration-run.mjs','utf8');
source=source.replace(/const variants=\[[\s\S]*?\];/,`const variants=[
 {id:'baseline',entry:'baseline',adapter:'node-adapter-before'},
 {id:'immediate-whole',entry:'hydration-native-count',adapter:'immediate-adapter'},
 {id:'immediate-callbacks',entry:'hydration-callbacks',adapter:'immediate-adapter'},
 {id:'immediate-records',entry:'hydration-records',adapter:'immediate-adapter'}
];`);
source=source.replaceAll('hydration-run.mjs','immediate-run.mjs').replaceAll('hydration-stream-adapter','immediate-adapter').replaceAll('hydration-http.json','immediate-http.json');
await writeFile(root+'immediate-run.mjs',source);
source=await readFile(root+'hydration-correctness.mjs','utf8');
source=source.replaceAll('hydration-stream-adapter','immediate-adapter').replaceAll('hydration-correctness.json','immediate-correctness.json');
// Establish that a transport write happens before the producer can advance,
// independently of final response equivalence. No string queue can pass this.
source+=`
const seen=[];
const response={statusCode:0,setHeader(){},write(chunk){seen.push(chunk);return true;},end(){seen.push('ended');}};
const result=createExactProducedResponse(200,{},write=>{
 write('<main>');assert.deepEqual(seen,['<main>']);
 write('text');assert.deepEqual(seen,['<main>','text']);
 write('</main>');assert.deepEqual(seen,['<main>','text','</main>']);
});
await writeNodeResponse(response,result);
assert.deepEqual(seen,['<main>','text','</main>','ended']);
console.log('Immediate forwarding verified inside the producer');
`;
await writeFile(root+'immediate-correctness.mjs',source);

