import {readFile,writeFile} from 'node:fs/promises';
import assert from 'node:assert/strict';
const root='.tmp/node-output-plan/';
let source=await readFile(root+'hydration-records.mjs','utf8');
const start=source.indexOf('var DirectSsrResumptionCapture = class {');
const end=source.indexOf('\nfunction createResumptionCapture(',start);
assert.ok(start>0&&end>start);
let capture=source.slice(start,end);
capture=capture.replace('records = [];','records = [];\n hydrationCallbacks = [];');
capture=capture.replace('this.publishedRootProps = publishedRootProps;','deferredHydrationCallbacks.set(this.records, this.hydrationCallbacks);\n\t\tthis.publishedRootProps = publishedRootProps;');
capture=capture.replace('this.records.splice(checkpoint);','this.records.splice(checkpoint);\n this.hydrationCallbacks.splice(checkpoint);');
capture=capture.replace('this.records.push([componentId]);',`this.records.push([componentId]);
  // Capture only record identity now. Serialization and response writes happen at the footer.
  this.hydrationCallbacks.push((emit, prefix) => emit(prefix + serializeJson(this.records[token])));`);
source=source.slice(0,start)+'const deferredHydrationCallbacks = new WeakMap();\n'+capture+source.slice(end);
const loop="for(let j=0;j<directResumptions.length;j++)emit((j?',':'')+serializeJson(directResumptions[j]));";
assert.ok(source.includes(loop));
source=source.replace(loop,`const callbacks=deferredHydrationCallbacks.get(directResumptions);
    for(let j=0;j<directResumptions.length;j++)callbacks[j](emit,j?',':'');`);
await writeFile(root+'hydration-registered.mjs',source);
// Separate instrumented artifact proves ordering, without adding instrumentation to timed workers.
source=source.replace('this.hydrationCallbacks.push((emit, prefix) => emit(prefix + serializeJson(this.records[token])));',`globalThis.__hydrationTrace.push('registered');
  this.hydrationCallbacks.push((emit, prefix) => {globalThis.__hydrationTrace.push('executed');emit(prefix + serializeJson(this.records[token]));});`);
await writeFile(root+'hydration-ordering.mjs',source);
let run=await readFile(root+'immediate-run.mjs','utf8');
run=run.replace("entry:'hydration-callbacks'","entry:'hydration-registered'");
run=run.replace("'hydration-callbacks',","'hydration-registered',");
await writeFile(root+'immediate-run.mjs',run);
let correctness=await readFile(root+'immediate-correctness.mjs','utf8');
correctness=correctness.replace("from './hydration-callbacks.mjs'","from './hydration-registered.mjs'");
