import {readFile,writeFile} from 'node:fs/promises';
import assert from 'node:assert/strict';
import ts from 'typescript';
const root='.tmp/node-output-plan/';
const source=await readFile(root+'hydration-registered.mjs','utf8');
const tree=ts.createSourceFile('entry.js',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.JS);
const edits=[];
function visit(node){
 if(ts.isFunctionDeclaration(node)&&node.name?.text==='utf8ByteLength')edits.push({start:node.body.pos,end:node.body.end,text:' { return 0; }'});
 if(ts.isFunctionDeclaration(node)&&node.name?.text==='escapeSsrText')edits.push({start:node.body.pos,end:node.body.end,text:' { return escapeText(value); }'});
 if(ts.isClassExpression(node)&&ts.isVariableDeclaration(node.parent)&&node.parent.name.getText(tree)==='SsrOutputBuffer'){
  for(const member of node.members)if(ts.isMethodDeclaration(member)&&['accountKnown','accountClosedBytes','account'].includes(member.name.getText(tree)))edits.push({start:member.body.pos,end:member.body.end,text:' {}'});
 }
 ts.forEachChild(node,visit);
}
visit(tree);assert.equal(edits.length,5);
let result=source;
for(const edit of edits.sort((a,b)=>b.start-a.start))result=result.slice(0,edit.start)+edit.text+result.slice(edit.end);
assert.ok(result.includes('payloadBytes+=Buffer.byteLength(value)'));
result=result.replace('payloadBytes+=Buffer.byteLength(value)','payloadBytes+=0').replace('byteTarget.hydrationBytes=Buffer.byteLength(prefix)+payloadBytes+9','byteTarget.hydrationBytes=0');
// Upper-bound diagnostic only: intentionally invalid returned byte counts and disabled byte limits.
// JSON/script escaping and graph validation remain; real HTTP bytes are validated by the client.
await writeFile(root+'immediate-unaccounted.mjs',result);
let run=await readFile(root+'immediate-run.mjs','utf8');
run=run.replace(/const variants=\[[\s\S]*?\];/,`const variants=[
 {id:'baseline',entry:'baseline',adapter:'node-adapter-before'},
 {id:'immediate-callbacks',entry:'hydration-registered',adapter:'immediate-adapter'},
 {id:'immediate-unaccounted',entry:'immediate-unaccounted',adapter:'immediate-adapter'}
];`);
run=run.replaceAll('immediate-run.mjs','immediate-unaccounted-run.mjs').replaceAll('immediate-http.json','immediate-unaccounted-http.json');
run=run.replace("'hydration-records',","'immediate-unaccounted',");
await writeFile(root+'immediate-unaccounted-run.mjs',run);

