import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {once} from 'node:events';
import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {createExactProducedResponse} from '@exactjs/server';
import {writeNodeResponse} from './immediate-adapter.mjs';
import {renderParticipantToSink as baseline} from './baseline.mjs';
import {renderParticipantToSink as callbacks} from './hydration-registered.mjs';
import {renderParticipantToSink as records} from './hydration-records.mjs';
const initial=JSON.parse(await readFile('.tmp/positional-leaves/data.json','utf8'));
const results=[];
for(const [name,candidate] of Object.entries({callbacks,records}))for(const text of ['plain ASCII','</script><script>alert(1)</script>\u2028\u2029 🚀 \ud800 & "']){
 const data=structuredClone(initial);
 data.incidents[0].title=text;
 let expected='';const bytes=baseline(data,'/incidents/inc-101',s=>expected+=s,Buffer.byteLength);
 const chunks=[];const actualBytes=candidate(data,'/incidents/inc-101',s=>chunks.push(s),Buffer.byteLength);
 assert.equal(chunks.join(''),expected);assert.equal(actualBytes,bytes);assert.equal(Buffer.byteLength(expected),bytes);
 const server=createServer((request,response)=>{
  const result=createExactProducedResponse(200,{'content-type':'text/html; charset=utf-8'},(write,environment)=>{
   candidate(data,'/incidents/inc-101',write,environment?.encodedByteLength);
  });
  void writeNodeResponse(response,result).catch(error=>response.destroy(error));
 });
 try{
  server.listen(0,'127.0.0.1');await once(server,'listening');
  const response=await fetch('http://127.0.0.1:'+server.address().port);
  const received=Buffer.from(await response.arrayBuffer());
  assert.equal(response.status,200);assert.deepEqual(received,Buffer.from(expected));
  results.push({name,input:text,bytes,chunks:chunks.length,sha256:createHash('sha256').update(received).digest('hex')});
 }finally{server.closeAllConnections();await new Promise((resolve,reject)=>server.close(error=>error?reject(error):resolve()));}
}
await writeFile('.tmp/node-output-plan/immediate-correctness.json',JSON.stringify({results},null,2));
console.log(results);

