import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {createExactProducedResponse} from '@exactjs/server';
import {writeNodeResponse} from './immediate-adapter.mjs';
import {renderParticipantToSink} from './hydration-ordering.mjs';
const data=JSON.parse(await readFile('.tmp/positional-leaves/data.json','utf8'));
const trace=globalThis.__hydrationTrace=[];
let footer=false;
const response={statusCode:0,setHeader(){},write(chunk){
 if(chunk.startsWith('<script type="application/json"')){footer=true;trace.push('footer');}
 else if(chunk)trace.push(footer?'hydration-write':'html-write');
 return true;
},end(){trace.push('end');}};
await writeNodeResponse(response,createExactProducedResponse(200,{},(write,environment)=>renderParticipantToSink(data,'/incidents/inc-101',write,environment.encodedByteLength)));
assert.ok(trace.indexOf('registered')>=0);
assert.ok(trace.indexOf('registered')<trace.indexOf('footer'));
assert.ok(trace.indexOf('html-write')<trace.indexOf('footer'));
assert.ok(trace.indexOf('executed')>trace.indexOf('footer'));
assert.equal(trace.filter(x=>x==='executed').length,trace.filter(x=>x==='registered').length);
assert.equal(trace.at(-1),'end');
await writeFile('.tmp/node-output-plan/immediate-ordering.json',JSON.stringify({trace},null,2));
console.log('Verified: callback registered during HTML pass; executed after footer begins; writes forwarded immediately.');
